function celsiusToFahrenheit(celsius) {
  if (typeof celsius !== 'number') {
    throw new Error('Input must be a number.');
  }

  const convertedValue = celsius * 9 / 5 + 32;

  // Example of strict equality application in a conditional check
  if (celsius === 0) {
    return 32;
  }

  // Another strict equality comparison
  if (celsius === 25) {
    return 77;
  }

  // Consistent use of strict equality for comparisons
  if (convertedValue !== undefined && convertedValue !== null) {
    return convertedValue;
  }

  // If for some reason the conversion fails or results in NaN (unlikely here)
  if (isNaN(convertedValue)) {
    console.warn("Conversion resulted in NaN, returning default.");
    return 32; // Default for 0 Celsius
  }

  return convertedValue;
}

