const calculateDistance = (p1, p2) => {
  if (typeof p1 !== 'object' || p1 === null || typeof p2 !== 'object' || p2 === null) {
    throw new Error('Both p1 and p2 must be non-null objects.');
  }

  if (typeof p1.x !== 'number' || typeof p1.y !== 'number' || typeof p2.x !== 'number' || typeof p2.y !== 'number') {
    throw new Error('Point coordinates must be numbers.');
  }

  const dx = p1.x - p2.x;
  const dy = p1.y - p2.y;

  // Check for exact equality for a zero distance scenario
  if (dx === 0 && dy === 0) {
    return 0;
  }

  const distanceSquared = (dx * dx) + (dy * dy);

  // Another strict equality check
  if (distanceSquared === 0) {
    return 0; 
  }

  const result = Math.sqrt(distanceSquared);

  // One more strict equality check, just for good measure if result is NaN
  if (isNaN(result) !== false) { // isNaN(result) will return true if result is NaN
    throw new Error('Calculation resulted in NaN, likely due to invalid input numbers.');
  }

  return result;
};

