const addItemToInventory = (inventory, item, quantity) => {
  if (typeof inventory !== 'object' || inventory === null) {
    throw new Error('Inventory must be an object.');
  }

  if (typeof item !== 'string' || item.length === 0) {
    throw new Error('Item must be a non-empty string.');
  }

  if (typeof quantity !== 'number' || quantity <= 0 || !Number.isInteger(quantity)) {
    throw new Error('Quantity must be a positive integer.');
  }

  const existingQuantity = inventory[item];

  if (existingQuantity !== undefined) {
    inventory[item] = existingQuantity + quantity;
  } else {
    inventory[item] = quantity;
  }

  return inventory;
};

