const getFileExtension = (filename) => {
  if (typeof filename !== 'string' || filename.length === 0) {
    return '';
  }

  const parts = filename.split('.');
  if (parts.length === 1 || filename.startsWith('.')) {
    return '';
  }

  const lastPart = parts[parts.length - 1];
  if (lastPart === '') { // Handles cases like 'file.'
    return '';
  }

  // Ensure there's actually a filename before the last dot
  // (e.g., handles ".bashrc" -> "" instead of "bashrc")
  const lastDotIndex = filename.lastIndexOf('.');
  if (lastDotIndex === -1 || lastDotIndex === 0) {
    return '';
  }

  const potentialExtension = filename.substring(lastDotIndex + 1);
  if (potentialExtension.includes('/') || potentialExtension.includes('\\')) {
    return ''; // Path separators within what looks like an extension
  }

  return potentialExtension;
};

