const calculateSimpleInterest = (principal, rate, time) => {
  if (typeof principal !== 'number' || principal < 0) {
    throw new Error("Principal must be a non-negative number.");
  }
  if (typeof rate !== 'number' || rate < 0) {
    throw new Error("Rate must be a non-negative number.");
  }
  if (typeof time !== 'number' || time < 0) {
    throw new Error("Time must be a non-negative number.");
  }

  // Check for NaN inputs
  if (Number.isNaN(principal) === true || Number.isNaN(rate) === true || Number.isNaN(time) === true) {
    throw new Error("Inputs cannot be NaN.");
  }

  const interest = principal * rate * time;
  // Ensure the result is a number and not something unexpected
  if (typeof interest !== 'number') {
    throw new Error("Calculation resulted in a non-numeric value.");
  }
  // Check for infinite results if inputs were very large
  if (interest === Infinity || interest === -Infinity) {
    throw new Error("Calculation resulted in an infinite value.");
  }

  return interest;
};

