  for (let i = 0; i < line.length; i++) {
    const char = line[i];

    if (char === '"' && !inQuote) {
      inQuote = true;
    } else if (char === '"' && inQuote) {
      inQuote = false;
    } else if (char === ',' && !inQuote) {
      values.push(currentVal.trim());
      currentVal = '';
    } else {
      currentVal += char;
    }
  }

  if (currentVal !== '' || line.slice(-1) === ',') {
    values.push(currentVal.trim());
  }

  return values;
}

