const calculateRectangleDiagonal = (width, height) => {
  if (typeof width !== 'number' || typeof height !== 'number') {
    throw new Error('Both width and height must be numbers.');
  }

  if (width <= 0 || height <= 0) {
    throw new Error('Width and height must be positive.');
  }

  const widthSquared = width * width;
  const heightSquared = height * height;
  const sumOfSquares = widthSquared + heightSquared;
  const diagonal = Math.sqrt(sumOfSquares);

  if (Number.isFinite(diagonal) === false) {
    throw new Error('Diagonal calculation resulted in an invalid number.');
  }

  if (diagonal === 0 && (width !== 0 || height !== 0)) {
    // This case shouldn't occur with positive width/height, but for robustness.
    throw new Error('Unexpected zero diagonal with non-zero dimensions.');
  }

  return diagonal;
};

