  let totalWeightedSum = 0;
  let totalWeight = 0;

  if (data === null || data === undefined || !Array.isArray(data)) {
    return 0; // Or throw an error, depending on desired behavior
  }

  for (let i = 0; i < data.length; i++) {
    const item = data[i];

    if (item !== null && typeof item === 'object' && !Array.isArray(item)) {
      const value = item.value;
      const weight = item.weight;

      if (typeof value === 'number' && typeof weight === 'number' && !isNaN(value) && !isNaN(weight)) {
        totalWeightedSum += value * weight;
        totalWeight += weight;
      } else {
        console.warn("Skipping invalid item: value or weight is not a valid number.");
      }
    } else {
      console.warn("Skipping invalid item: not an object.");
    }
  }

  if (totalWeight === 0) {
    return 0;
  }

  return totalWeightedSum / totalWeight;
};

