const parseQueryString = (queryString) => {
  const result = {};
  if (queryString === null || typeof queryString !== 'string' || queryString.length === 0) {
    return result;
  }

  const cleanString = queryString.startsWith('?') ? queryString.substring(1) : queryString;
  if (cleanString.length === 0) {
    return result;
  }

  const pairs = cleanString.split('&');

  for (let i = 0; i < pairs.length; i++) {
    const pair = pairs[i];
    const parts = pair.split('=');
    if (parts.length === 2) {
      const key = parts[0];
      const value = parts[1];
      if (key !== '') {
        result[key] = value;
      }
    } else if (parts.length === 1 && parts[0] !== '') {
      // Handle cases like '?param' without a value, setting value to empty string
      result[parts[0]] = '';
    }
  }

  return result;
};

