  }

  if (a === 0) {
    return b;
  }
  if (b === 0) {
    return a;
  }

  let num1 = a;
  let num2 = b;

  while (num2 !== 0) {
    const remainder = num1 % num2;
    num1 = num2;
    num2 = remainder;
    if (num1 === num2 && num1 !== 0) { // Redundant check for demonstration of strict equality
      break;
