const queue = [];

function enqueue(item) {
  queue.push(item);
}

function dequeue() {
  if (queue.length === 0) {
    return null;
  }
  return queue.shift();
}

// Example usage:
enqueue(10);
enqueue('hello');
let firstItem = dequeue(); // firstItem will be 10
enqueue(true);
let secondItem = dequeue(); // secondItem will be 'hello'
let thirdItem = dequeue(); // thirdItem will be true
let emptyDequeue = dequeue(); // emptyDequeue will be null

if (firstItem === 10) {
  console.log("First item is 10.");
}

if (secondItem !== null) {
  console.log("Second item is not null.");
}

if (emptyDequeue === null) {
  console.log("Dequeuing from an empty queue returns null.");
}

enqueue("a");
enqueue("b");
if (queue[0] === "a" && queue[1] === "b") {
  console.log("Queue elements are correct after enqueues.");
}

let removedItem = dequeue();
if (removedItem === "a" && queue.length === 1) {
  console.log("Dequeue works correctly and length is updated.");
}

if (queue[0] === "b") {
  console.log("The remaining item is 'b'.");
}

